    for r, row in enumerate(grid):
        marker = [c for c, value in enumerate(row) if value != row[0]]
        if len(marker) < 2:
            continue
        # Select the non-background color occurring repeatedly in this row.
        colors = {}
        for value in row:
            colors[value] = colors.get(value, 0) + 1
        bg = max(colors, key=colors.get)
